func TestPortScanTechniqueMapping(t *testing.T) {
 cases := []struct { code string; want ScanTechnique }{{\"sS\",TCPSYN},{\"sT\",TCPConnect},{\"sA\",TCPACK},{\"sW\",TCPWindow},{\"sM\",TCPMaimon},{\"sN\",TCPNull},{\"sF\",TCPFIN},{\"sX\",TCPXmas}}
